import licenses from './licenses.json';

/** Each shipped package with its full licence text (generated by `npm run build:licenses`). */
export default function LicenseList() {
  return (
    <ul className="flex flex-col gap-1">
      {licenses.packages.map((pkg) => (
        <li key={`${pkg.name}@${pkg.version}`}>
          <details className="rounded-lg border border-stone-200 bg-white">
            <summary className="flex min-h-11 cursor-pointer items-center gap-2 px-3 text-base">
              <span className="font-medium">{pkg.name}</span>
              <span className="text-sm text-stone-600">
                {pkg.version} · {pkg.license}
              </span>
            </summary>
            <pre className="overflow-x-auto px-3 pb-3 text-xs whitespace-pre-wrap">{pkg.text}</pre>
          </details>
        </li>
      ))}
    </ul>
  );
}
